const copy = (lang) => UI[lang] || UI.en;
const levelText = (tr, level) => ({CRITICAL:tr.critical,HIGH:tr.high,MODERATE:tr.moderate,LOW:tr.low}[level] || level);
const dynamicText = (tr, value) => {
  if (!value) return value;
  const v = String(value).toLowerCase();
  if (v.includes("rising") || v.includes("increase") || v.includes("increasing")) return tr.rising;
  if (v.includes("normal") || v.includes("stable")) return tr.normal;
  if (v.includes("monitor")) return tr.monitor;
  if (v.includes("prepare")) return tr.prepare;
  if (v.includes("evac")) return tr.evacuate;
  return value;
};
const riskColor = {CRITICAL:"critical",HIGH:"high",MODERATE:"moderate",LOW:"low"};
const iconCache = {};
function riskIcon(level){
  if(!iconCache[level]){
    const label = level === "CRITICAL" ? "!" : level === "HIGH" ? "▲" : level === "MODERATE" ? "◆" : "•";
    iconCache[level] = L.divIcon({className:"risk-marker-wrap",html:`<div class="risk-marker ${level.toLowerCase()}"><span>${label}</span></div>`,iconSize:[50,50],iconAnchor:[25,25]});
  }
  return iconCache[level];
}
function pointIcon(cls,label){return L.divIcon({className:"layer-marker-wrap",html:`<div class="layer-marker ${cls}">${label}</div>`,iconSize:[34,34],iconAnchor:[17,17]});}
